(async () => {
if (figma.root.name !== 'SOHO') throw new Error('WRONG FILE');
const NS = 'soho';
const page = figma.root.children.find(p => p.name === '01 Design');
await page.loadAsync();
await figma.setCurrentPageAsync(page);
const root = page.findOne(n => n.getSharedPluginData(NS, 'key') === "home-hero-1440");
if (!root) throw new Error('no root');
const ITEMS = [{"match":"ảnh ghim: Le Viva Resort","file":"le-viva-resort.png"},{"match":"ảnh ghim: King Decor Luxury","file":"king-decor-luxury.png"},{"match":"ảnh ghim: Kronos Luxury Timepieces","file":"kronos-luxury-timepieces.png"},{"match":"ảnh ghim: Helen Bridal","file":"helen-bridal.png"},{"match":"decor flag","file":"flag.png","fit":"FIT"},{"match":"banner C","file":"banner-c.png"},{"match":"slot: JourneyMatrix","file":"journey.png","slot":true},{"match":"slot: Track 4 bước","file":"process.png","slot":true}];
const B64 = {"le-viva-resort.png":"","king-decor-luxury.png":"","kronos-luxury-timepieces.png":"","helen-bridal.png":"","flag.png":"","banner-c.png":"","journey.png":"","process.png":""};
const done = [], errors = [];
for (const it of ITEMS) {
  const node = root.findOne(n => n.name.startsWith(it.match) && (n.type === 'RECTANGLE' || n.type === 'FRAME'));
  if (!node) { errors.push('not found ' + it.match); continue; }
  const img = figma.createImage(figma.base64Decode(B64[it.file]));
  const size = await img.getSizeAsync();
  if (it.slot) {
    for (const c of [...node.children]) c.remove();
    node.strokes = [];
    node.dashPattern = [];
    const w = node.width;
    node.resize(w, Math.round((size.height / size.width) * w));
    node.layoutSizingVertical = 'FIXED';
  }
  node.fills = [{type: 'IMAGE', imageHash: img.hash, scaleMode: it.fit || 'FILL'}];
  done.push(it.match);
}
return {done, errors};
})()